## Code Example
```javascript
// Pseudo-durable orchestrator sketch
const df = require('durable-functions');
module.exports = df.app();
async function orchestrator(context) {
  const blobName = context.bindingData.name;
  const imageId = blobName; // dedupe key
  // check existing in Cosmos, then upsert
  // fan-out to Resize activities
  const outputs = await context.df.Task.all([
    context.df.callActivity('ResizeA', {imageId}),
    context.df.callActivity('ResizeB', {imageId}),
    context.df.callActivity('ResizeC', {imageId})
  ]);
  await context.df.callActivity('UpsertMetadata', {imageId, userId: context.bindingData.userId});
  await context.df.callActivity('PublishStatus', {imageId});
  return outputs;
}
```

